		String result = "";
		 if(washer!= null && washer.getStaffs() != null && washer.getStaffs().size() > 0){
			 for(Staff staff : washer.getStaffs()) {
				 if (staff.getUser() != null && staff.getUser().contains(userId)) {
					 return staff.getRole();
				 }
			 }
		 }
		return result;
	}

