	public static LinkedHashMap<Integer,Integer> getGroupedServices(List<Integer> services){
		if(services == null){
			return new LinkedHashMap<>();
		}
		return services.stream().collect(Collectors.toMap(
				service -> service,
				service -> 1,
				Integer::sum,
				LinkedHashMap::new
		));
	}

