		if(staffs != null) {
			return staffs.stream()
					.filter(staff -> staffId.equals(staff.getUid()))
					.map(staff -> staff.getFirstName() + " " + (!TextUtils.isEmpty(staff.getLastName().trim()) ? staff.getLastName() : ""))
					.findFirst()
					.orElse("");
		}
		return "";
	}


